def test_link_api():
    with open("./journals.txt", "r+",encoding="utf-8") as f:
        journals = f.readlines()
    f.close()
    journals = [i.replace("\n", "") for i in journals]

    for journal in journals:
        next_cursor = "*"
        while True:
            print(journal)
            start_time = time.time()
            query_text =  '{"c":150,"q":[{"k":"hasSourcetitle_snt","v": '+f'"{journal}"'+',"o":"OR","a":1},{"k":"sysDataStatus","v":"enable","o":"AND","a":1}],"op":"AND","s":["id:asc"],"t":["Z01"]}'
            # query_text =  '{"c":100,"q":[{"k":"hasSourcetitle_snt","v": "出口商品包装：软包装","o":"OR","a":1},{"k":"sysDataStatus","v":"enable","o":"AND","a":1}],"op":"AND","s":["id:asc"],"t":["Z01"]}'
            # query_text = query_text.encode("utf-8")
            # query_text = urlencode(query_text)
            # query_text = str(query_text)
            api_url = 'http://127.0.0.1:14106/api/service/extract/data-handle/interface/getArticle?fields=id,title,abstract,entityType,year,createTime,language,doi,hasSourcetitle,publisher,hasSourcesysSourceId&nextCursor=' + next_cursor + '&queryText='+query_text

            res = requests.get(api_url)
            res = json.loads(res.text)

            if res['code']==-1:
                break

            cur_data = res['data']
            datas = cur_data['data']

            if not datas or datas=="":
                break

            next_cursor = cur_data['cursor']

            end_time = time.time()
            print(end_time - start_time)

def test_link_Mlivus():
    # -*- coding: utf-8 -*-
    # docker run  -it -p 19530:19530 -d milvusdb/milvus:cpu-latest
    # 导入相应的包
    # -*- coding: utf-8 -*-
    # docker run  -it -p 19530:19530 -d milvusdb/milvus:cpu-latest
    # 导入相应的包
    import numpy as np
    from pymilvus import Milvus, IndexType
    import time

    t1 = time.time()
    # 初始化一个Milvus类，以后所有的操作都是通过milvus来的
    milvus = Milvus(host='127.0.0.1', port='19530')
    vec_dim = 1000  # 向量的维度
    num_vec = 9999  # 向量数量10000，后面还加入了一条和查询向量一样的做验证
    # 删除collection
    milvus.drop_collection('test01')
    # 创建collection
    param = {'collection_name': 'test01', 'dimension': vec_dim, 'index_file_size': 1024, 'metric_type': MetricType.L2}
    milvus.create_collection(param)
    # 建立分区
    milvus.create_partition('test01', 'tag01')

    # nlist聚类为多少簇
    ivf_param = {'nlist': 16, 'm': 40, 'nbits': 8}
    milvus.create_index('test01', IndexType.IVF_PQ, ivf_param)
    # 随机生成一批向量数据
    vectors_array = np.random.rand(num_vec, vec_dim)
    vectors_list = vectors_array.tolist()
    vectors_list.append([1 for _ in range(vec_dim)])
    # 单次插入的数据量不能大于 256 MB，插入后存在缓存区，缓存区大小由参数index_file_size决定，默认1024M
    milvus.insert(collection_name='test01', records=vectors_list, partition_tag="tag01")
    # 一些信息
    print(milvus.list_collections())
    print(milvus.get_collection_info('test01'))
    t2 = time.time()
    print("create cost:", t2 - t1)
    # # 创建查询向量
    query_vec_list = [[1 for _ in range(vec_dim)]]
    # 进行查询, 注意这里的参数nprobe和建立索引时的参数nlist 会因为索引类型不同而影响到查询性能和查询准确率
    # nprobe 不能超过 nlist。
    search_param = {'nprobe': 10}
    # 现在数据还在内存，需要数据落盘，保存到数据库中去，不然查不到数据
    milvus.flush(collection_name_array=['test01'])
    results = milvus.search(collection_name='test01', query_records=query_vec_list, top_k=10, params=search_param)
    print(results)
    print("search cost:", time.time() - t2)


