import  re

def find_info(pattern,str_info):
    return re.compile(rf"<{pattern}>(.*?)</{pattern}>",re.M).findall(str_info)

def find_sub_info(info_lists,name_lists):
    author_result = []
    for author in info_lists:
        temp = []
        for name in name_lists:
            temp.append("".join(find_info(name, author)))
        author_result.append("<+>".join(temp))
    return "<::>".join(author_result)

# res = re.findall("<paper>(.*?)</paper>",xml_str)

papers = find_info("paper", xml_str)

sig_name = ["id","title","abstract","language","sysProcessingUnit","classificationCode","hasHoldinglibraryCode","entityType","year","volume","issue","startPage","endPage","pageCount","accessType","createTime","","","","","","","","","","","","","","","","","","","","","","",""]

for paper in papers:

    authors = find_info("hasAuthor",paper)
    author_result = find_sub_info(authors,["id","name"])

    hasSource = find_info("hasSource", paper)
    hasSource_result = find_sub_info(hasSource, ["id", "sysSourceId","title"])

    hasFile = find_info("hasFile", paper)
    hasFile_result = find_sub_info(hasFile, ["id", "fileType"])

    hasCreateOrganization = find_info("hasCreateOrganization", paper)
    hasCreateOrganization_result = find_sub_info(hasCreateOrganization, ["id", "name"])


    print(author_result)
    print(hasSource_result)
    print(hasFile_result)
    print(hasCreateOrganization_result)
